package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "empty input",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:    []string{"hello"},
		},
		{
			name:  "multiple words fit on one line",
			text:  "hello world",
			width: 20,
			want:   []string{"hello world"},
		},
		{
			name:  "multiple lines needed",
			text:  "hello world foo bar",
			width: 10,
			want:   []string{"hello", "world foo", "bar"},
		},
		{
			name:  "word longer than width",
			text:  "superlongword short",
			width: 5,
			want:   []string{"superlongword", "short"},
		},
		{
			name:  "width zero",
			text:  "hello",
			width: 0,
			want:   nil,
		},
		{
			name:  "negative width",
			text:  "hello",
			width: -1,
			want:   nil,
		},
		{
			name:  "extra whitespace collapses",
			text:  "  hello   world  ",
			width: 20,
			want:   []string{"hello world"},
		},
		{
			name:  "exact width fit",
			text:  "hello world",
			width: 11,
			want:   []string{"hello world"},
		},
		{
			name:  "exact boundary forces break",
			text:  "hello world",
			width: 10,
			want:   []string{"hello", "world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == len(tt.want) && (got == nil && tt.want == nil || (got != nil && tt.want != nil)) {
				if got == nil && tt.want == nil {
					return
				}
				for i := range got {
					if got[i] != tt.want[i] {
						t.Errorf("got %v, want %v", got, tt.want)
						break
					}
				}
				return
			}
			t.Errorf("Wrap(%q, %d) = %v, want %v", tt.text, tt.width, got, tt.want)
		})
	}
}

